# Create an empty dictionary to store student grades
student_grades = {}

def add_student(student_name):
    """Add a new student to the dictionary with an empty list of grades"""
    if student_name not in student_grades:
        student_grades[student_name] = []

def add_grade(student_name, grade):
    """Add a grade to the list of grades for a student"""
    if student_name not in student_grades:
        add_student(student_name)
    student_grades[student_name].append(grade)

def calculate_average(student_name):
    """Calculate the average grade for a student"""
    if student_name in student_grades:
        grades = student_grades[student_name]
        return sum(grades) / len(grades)
    else:
        return "Student not found"

# Example usage
add_student("John")
add_grade("John", 90)
add_grade("John", 85)
print(calculate_average("John"))  # Output: John's average grade: 87.5
```

This program defines three functions: `add_student`, `add_grade`, and `calculate_average`. The `add_student` function adds a new student to the dictionary with an empty list of grades. The `add_grade` function adds a grade to the list of grades for a student. The `calculate_average` function calculates the average grade for a student by summing up all the grades in the list and dividing by the number of grades. The function returns the average grade or a message indicating that the student was not found in the dictionary.
